function audioWave(clip){const raw=clip.cloudRaw||{},peaks=clip.peaks||raw.waveformPeaks||raw.waveform_peaks||raw.peaks;if(Array.isArray(peaks)&&peaks.length){const values=peaks.map(v=>Array.isArray(v)?Math.max(...v.map(Math.abs)):Math.abs(Number(v)||0));return `<svg viewBox="0 0 200 42" preserveAspectRatio="none"><path d="${values.map((v,i)=>`M${i/values.length*200} ${21-Math.min(1,v)*18}v${Math.min(1,v)*36}`).join(' ')}" stroke="#c2cfe4" stroke-width=".6" fill="none"/></svg>`;}return '<div class="audio-clip-label">CLOUD AUDIO</div>';}
