function noHostProject(){engine.monitor.stop();engine.stopRealtime();$('#project-title').textContent='No project open';$('#hint').textContent='Open a project in Freestyle Studio to edit it in Modesty.';toast('Open a project in Freestyle Studio to edit it in Modesty.');}
function openHostProject(id){setCloudPanelProject(id);if(!id){noHostProject();return;}if(id!==engine.projectId||!engine.ready&&!engine.loading)engine.load(id).catch(fail);}
let hostRefreshTimer=null,hostChangedWhileHidden=false;
function refreshFromHost(){clearTimeout(hostRefreshTimer);hostRefreshTimer=setTimeout(()=>{hostRefreshTimer=null;if(engine.ready&&!engine.loading&&!engine.interacting&&studioViewActive())engine.refresh().catch(fail);},250);}
function suspendView(){
 // Another Studio view is active: go silent and pause clock/poll/render loops (the peer stays up). Playback stops
 // too, unless the host keeps the transport rolling across views (continuousTransport); a take always ends here.
 clearTimeout(hostRefreshTimer);
 if(recording)toggleRecord().catch(fail);
 const keepRolling=hostCapability('continuousTransport');
 const halt=engine.ready&&!keepRolling&&(engine.playing||engine.previewing||engine.playAttempt)?engine.pause().catch(()=>{}):Promise.resolve();
 engine.silenceMonitorSink();engine.realtime?.subscribeClock?.(false);if(!keepRolling)syncPlayButton(false);
 halt.finally(()=>setTimeout(()=>{if(!studioViewActive())engine.session.stopTicking?.();},120));
}
function resumeView(){
 // Active again: resume at once, re-check the peer, and pick up what changed in the other view.
 engine.realtime?.subscribeClock?.(true);syncPlayButton(engine.playing);
 if(!engine.ready||engine.loading){const id=hostProjectId();if(id&&id!==engine.projectId)openHostProject(id);return;}
 engine.session.startTicking?.();
 // Playback may have started or stopped in another view: read the engine clock now, not on the next poll.
 Promise.resolve(engine.session.refreshTransportClock?.()).then(()=>syncPlayButton(engine.playing),()=>{});
 const monitor=engine.monitor;if(['error','disconnected','reconnecting'].includes(monitor.state))monitor.reconnectNow?.();else if(monitor.state==='idle')engine.warmMonitor();
 hostChangedWhileHidden=false;refreshFromHost();
}
try{
 attachHostLifecycle({onProject:id=>openHostProject(id),onProjectUpdated:()=>{if(studioViewActive())refreshFromHost();else hostChangedWhileHidden=true;},onInactive:suspendView,onActive:resumeView});
 getCloudStatus().catch(fail);prefetchStudioContract();openHostProject(hostProjectId());
 if(!studioViewActive())suspendView();
}catch(error){fail(error);$('#hint').textContent=error.detail||error.message;}
// Small read-only diagnostic surface for verifying the currently running workstation.
window.modesty=window.vegetableStudio={get project(){return clone(project);},get playing(){return engine.playing;},get mode(){return mode;},engine,windows,timelineViewport,pianoViewport,audacityUi,version:'0.4.0-audacity-cloud'};

$('#mode').classList.add('song');

$('.monitor').title='Connect live Freestyle cloud audio';$('.monitor').style.cursor='pointer';$('.monitor').onclick=()=>engine.startMonitor().catch(fail);$('.monitor').oncontextmenu=e=>{e.preventDefault();menu(e,[['Connect live cloud audio','',()=>engine.startMonitor()],['Listen to rendered cloud preview','',()=>engine.listenPreview()]]);};

document.addEventListener('pointerdown',e=>{if(e.target.closest('#desktop .step,#desktop .clip,#desktop .piano-note,#desktop input[type=range],#desktop .small-knob,#piano-grid,#velocity-grid'))engine.interacting=true;},true);
function finishPointerInteraction(){if(engine.interacting){engine.interacting=false;if(engine.pending)engine.update(engine.pending);}}
document.addEventListener('pointerup',finishPointerInteraction,true);document.addEventListener('pointercancel',finishPointerInteraction,true);window.addEventListener('blur',finishPointerInteraction);

$('#piano-more').onclick=pianoMenu;

document.addEventListener('keyup',e=>{const held=activeKeyboardNotes.get(e.code);if(held){activeKeyboardNotes.delete(e.code);engine.noteOff(held.channel,held.pitch).catch(fail);}if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))finishPointerInteraction();});window.addEventListener('blur',()=>{activeKeyboardNotes.clear();engine.releaseNotes();});

$('#rack').addEventListener('dragover',e=>{if([...e.dataTransfer.types].includes('application/vegetable-library-sound')){e.preventDefault();e.dataTransfer.dropEffect='copy';$('#rack').classList.add('library-drop-target');}});
$('#rack').addEventListener('dragleave',e=>{if(!$('#rack').contains(e.relatedTarget))$('#rack').classList.remove('library-drop-target');});
$('#rack').addEventListener('drop',e=>{const raw=e.dataTransfer.getData('application/vegetable-library-sound');if(!raw)return;e.preventDefault();e.stopPropagation();$('#rack').classList.remove('library-drop-target');try{const item=JSON.parse(raw);if(!item.id||!cloudLibrary)throw new Error('Choose a sound returned by the cloud library.');cloudLibrary.execute(()=>cloudLibrary.addSound(item));}catch(error){fail(error);}});
